import{c as e,Q as a,j as s,m as l}from"./chunks/framework.7r1mYKiJ.js";const y=JSON.parse('{"title":"Commands & Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/commands-permissions.md","filePath":"configuration/commands-permissions.md"}'),i={name:"configuration/commands-permissions.md"};function d(n,t,o,r,h,c){return a(),s("div",null,[...t[0]||(t[0]=[l(`<h1 id="commands-permissions" tabindex="-1">Commands &amp; Permissions <a class="header-anchor" href="#commands-permissions" aria-label="Permalink to &quot;Commands &amp; Permissions&quot;">​</a></h1><p>This page covers every command available in AetherUHC, who can use it, and what permission node is required.</p><h2 id="permission-nodes-summary" tabindex="-1">Permission Nodes Summary <a class="header-anchor" href="#permission-nodes-summary" aria-label="Permalink to &quot;Permission Nodes Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Permission</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>aetheruhc.host</code></td><td style="text-align:left;">Access to all match hosting, configuration, and scenario management</td></tr><tr><td style="text-align:left;"><code>aetheruhc.admin</code></td><td style="text-align:left;">Server-level administration (reload, setlobby, debug tools)</td></tr><tr><td style="text-align:left;"><code>aetheruhc.stats.others</code></td><td style="text-align:left;">Allows viewing another player&#39;s stats with <code>/stats &lt;player&gt;</code></td></tr><tr><td style="text-align:left;"><em>(none required)</em></td><td style="text-align:left;">Default player commands accessible to all players</td></tr></tbody></table><hr><h2 id="host-commands" tabindex="-1">Host Commands <a class="header-anchor" href="#host-commands" aria-label="Permalink to &quot;Host Commands&quot;">​</a></h2><p>These commands require the <code>aetheruhc.host</code> permission and are used to configure and run the match. The primary interface is the <strong>Host GUI</strong> accessible via <code>/host</code>.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Description</th><th style="text-align:left;">Permission</th></tr></thead><tbody><tr><td style="text-align:left;"><code>/host</code></td><td style="text-align:left;">Opens the main Host configuration GUI.</td><td style="text-align:left;"><code>aetheruhc.host</code></td></tr><tr><td style="text-align:left;"><code>/scenarios</code></td><td style="text-align:left;">Opens the Scenario Manager GUI.</td><td style="text-align:left;"><code>aetheruhc.host</code></td></tr><tr><td style="text-align:left;"><code>/scenario enable &lt;name&gt;</code></td><td style="text-align:left;">Enables a specific scenario by alias.</td><td style="text-align:left;"><code>aetheruhc.host</code></td></tr><tr><td style="text-align:left;"><code>/scenario disable &lt;name&gt;</code></td><td style="text-align:left;">Disables a specific scenario by alias.</td><td style="text-align:left;"><code>aetheruhc.host</code></td></tr><tr><td style="text-align:left;"><code>/scenarios off</code></td><td style="text-align:left;">Disables all currently active scenarios.</td><td style="text-align:left;"><code>aetheruhc.host</code></td></tr><tr><td style="text-align:left;"><code>/start</code></td><td style="text-align:left;">Starts the UHC match (triggers scatter and countdown).</td><td style="text-align:left;"><code>aetheruhc.host</code></td></tr><tr><td style="text-align:left;"><code>/end</code></td><td style="text-align:left;">Forcibly ends the current match.</td><td style="text-align:left;"><code>aetheruhc.host</code></td></tr><tr><td style="text-align:left;"><code>/heal [player|all]</code></td><td style="text-align:left;">Heals a specific player or all players to full health.</td><td style="text-align:left;"><code>aetheruhc.host</code></td></tr><tr><td style="text-align:left;"><code>/feed [player|all]</code></td><td style="text-align:left;">Fills the hunger bar of a specific player or all players.</td><td style="text-align:left;"><code>aetheruhc.host</code></td></tr><tr><td style="text-align:left;"><code>/revive &lt;player&gt;</code></td><td style="text-align:left;">Revives a dead/spectating player and teleports them to their death location.</td><td style="text-align:left;"><code>aetheruhc.host</code></td></tr><tr><td style="text-align:left;"><code>/freeze [player|all]</code></td><td style="text-align:left;">Freezes one or all players in place (useful before scatter).</td><td style="text-align:left;"><code>aetheruhc.host</code></td></tr><tr><td style="text-align:left;"><code>/config</code></td><td style="text-align:left;">Opens the match configuration panel (border, grace period, etc.).</td><td style="text-align:left;"><code>aetheruhc.host</code></td></tr><tr><td style="text-align:left;"><code>/config admin</code></td><td style="text-align:left;">Opens the advanced host admin panel (meetup time, deathmatch settings).</td><td style="text-align:left;"><code>aetheruhc.host</code></td></tr></tbody></table><hr><h2 id="player-commands" tabindex="-1">Player Commands <a class="header-anchor" href="#player-commands" aria-label="Permalink to &quot;Player Commands&quot;">​</a></h2><p>These commands are available to all connected players by default, regardless of permissions.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Description</th><th style="text-align:left;">Permission</th></tr></thead><tbody><tr><td style="text-align:left;"><code>/scenarios</code></td><td style="text-align:left;">View all currently active scenarios (read-only).</td><td style="text-align:left;"><em>(none)</em></td></tr><tr><td style="text-align:left;"><code>/stats</code></td><td style="text-align:left;">View your own all-time UHC statistics (kills, deaths, wins, KDR).</td><td style="text-align:left;"><em>(none)</em></td></tr><tr><td style="text-align:left;"><code>/stats &lt;player&gt;</code></td><td style="text-align:left;">View another player&#39;s statistics.</td><td style="text-align:left;"><code>aetheruhc.stats.others</code></td></tr><tr><td style="text-align:left;"><code>/leaderboard</code></td><td style="text-align:left;">View the top players on the server by kills or wins.</td><td style="text-align:left;"><em>(none)</em></td></tr><tr><td style="text-align:left;"><code>/rules</code></td><td style="text-align:left;">Read the current match rules and any host notes.</td><td style="text-align:left;"><em>(none)</em></td></tr><tr><td style="text-align:left;"><code>/ping</code></td><td style="text-align:left;">Check your connection latency to the server.</td><td style="text-align:left;"><em>(none)</em></td></tr><tr><td style="text-align:left;"><code>/helpop &lt;message&gt;</code></td><td style="text-align:left;">Send a private help message to all online hosts and moderators.</td><td style="text-align:left;"><em>(none)</em></td></tr><tr><td style="text-align:left;"><code>/teaminventory</code></td><td style="text-align:left;">Open the shared team inventory <em>(requires Back Packs scenario)</em>.</td><td style="text-align:left;"><em>(none)</em></td></tr><tr><td style="text-align:left;"><code>/backpack</code></td><td style="text-align:left;">Open your personal extra inventory <em>(requires Extra Inventory scenario)</em>.</td><td style="text-align:left;"><em>(none)</em></td></tr><tr><td style="text-align:left;"><code>/recon</code></td><td style="text-align:left;">Spend a recon charge to view an enemy&#39;s inventory <em>(requires Enemy Recon scenario)</em>.</td><td style="text-align:left;"><em>(none)</em></td></tr><tr><td style="text-align:left;"><code>/genie wish &lt;reward&gt;</code></td><td style="text-align:left;">Redeem a genie wish for a reward <em>(requires Genie scenario)</em>.</td><td style="text-align:left;"><em>(none)</em></td></tr></tbody></table><hr><h2 id="admin-commands" tabindex="-1">Admin Commands <a class="header-anchor" href="#admin-commands" aria-label="Permalink to &quot;Admin Commands&quot;">​</a></h2><p>These commands are intended for server administrators who manage the plugin installation, not for match hosts.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Description</th><th style="text-align:left;">Permission</th></tr></thead><tbody><tr><td style="text-align:left;"><code>/aetheruhc reload</code></td><td style="text-align:left;">Reloads all configuration files and language files without a server restart.</td><td style="text-align:left;"><code>aetheruhc.admin</code></td></tr><tr><td style="text-align:left;"><code>/aetheruhc setlobby</code></td><td style="text-align:left;">Sets the global lobby spawn point to your current location.</td><td style="text-align:left;"><code>aetheruhc.admin</code></td></tr><tr><td style="text-align:left;"><code>/aetheruhc debug</code></td><td style="text-align:left;">Prints internal plugin state to console for troubleshooting.</td><td style="text-align:left;"><code>aetheruhc.admin</code></td></tr><tr><td style="text-align:left;"><code>/aetheruhc version</code></td><td style="text-align:left;">Displays the current plugin version and build info.</td><td style="text-align:left;"><code>aetheruhc.admin</code></td></tr><tr><td style="text-align:left;"><code>/aetheruhc pregen status</code></td><td style="text-align:left;">Shows the current pre-generation progress (chunks complete, ETA).</td><td style="text-align:left;"><code>aetheruhc.admin</code></td></tr><tr><td style="text-align:left;"><code>/aetheruhc pregen cancel</code></td><td style="text-align:left;">Cancels an in-progress pre-generation run.</td><td style="text-align:left;"><code>aetheruhc.admin</code></td></tr></tbody></table><hr><h2 id="command-aliases" tabindex="-1">Command Aliases <a class="header-anchor" href="#command-aliases" aria-label="Permalink to &quot;Command Aliases&quot;">​</a></h2><p>Several frequently-used commands have shorter aliases:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Full Command</th><th style="text-align:left;">Alias</th></tr></thead><tbody><tr><td style="text-align:left;"><code>/aetheruhc</code></td><td style="text-align:left;"><code>/auhc</code></td></tr><tr><td style="text-align:left;"><code>/scenarios</code></td><td style="text-align:left;"><code>/s</code> <em>(if enabled in config)</em></td></tr><tr><td style="text-align:left;"><code>/leaderboard</code></td><td style="text-align:left;"><code>/lb</code></td></tr><tr><td style="text-align:left;"><code>/teaminventory</code></td><td style="text-align:left;"><code>/ti</code></td></tr></tbody></table><hr><h2 id="configuring-command-access" tabindex="-1">Configuring Command Access <a class="header-anchor" href="#configuring-command-access" aria-label="Permalink to &quot;Configuring Command Access&quot;">​</a></h2><p>By default, all permissions are configured to work with LuckPerms, but any compatible permissions plugin (PermissionsEx, GroupManager) will work. To grant host access to a player:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># LuckPerms</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/lp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">playe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> permission</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aetheruhc.host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># PermissionsEx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/pex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">playe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aetheruhc.host</span></span></code></pre></div><p>To create a persistent &quot;Host&quot; group:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/lp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> group</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> permission</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aetheruhc.host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/lp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">playe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> parent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> host</span></span></code></pre></div>`,26)])])}const p=e(i,[["render",d]]);export{y as __pageData,p as default};
